namespace sv_76158056ed7642f2afd49f8805c0050a.Services;

/// <summary>
/// Scoped service that holds the currently selected warehouse for a single circuit.
/// Registered as Scoped so each Blazor Server circuit (user session) gets its own instance.
/// </summary>
public sealed class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId => _currentWarehouseId;

    public event Action? OnWarehouseChanged;

    public void SetWarehouse(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;
        _currentWarehouseId = warehouseId;
        OnWarehouseChanged?.Invoke();
    }

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("WH-001", "Warehouse A — Main Distribution"),
        ("WH-002", "Warehouse B — East Region"),
        ("WH-003", "Warehouse C — West Region"),
    ];
}

namespace sv_76158056ed7642f2afd49f8805c0050a.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts and a polling mechanism.
/// Each circuit gets its own instance, so concurrent users are fully isolated.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _timer;
    private int _subscriberCount;
    private int _lastKnownCount;

    /// <summary>Fires whenever new alert data has been fetched.</summary>
    public event Action<int>? OnAlertCountUpdated;

    public int LastKnownCount => _lastKnownCount;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    /// <summary>Simulates a database query; returns a random count 0–15.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Components call this to start polling. Polling begins on the first subscriber
    /// and stops when the last subscriber leaves.
    /// </summary>
    public void Subscribe()
    {
        _subscriberCount++;
        if (_subscriberCount == 1) StartPolling();
    }

    public void Unsubscribe()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0) StopPolling();
    }

    private void StartPolling()
    {
        _timer?.Dispose();
        _timer = new Timer(async _ => await PollAsync(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
    }

    private void StopPolling()
    {
        _timer?.Dispose();
        _timer = null;
    }

    private async Task PollAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _lastKnownCount = count;
        OnAlertCountUpdated?.Invoke(count);
    }

    private async void HandleWarehouseChanged()
    {
        // Immediately re-poll when the warehouse changes so all subscribers get fresh data.
        if (_subscriberCount > 0)
        {
            await PollAsync();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        StopPolling();
    }
}

