@using sv_76158056ed7642f2afd49f8805c0050a.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable
@rendermode InteractiveServer

<select class="form-select form-select-sm" style="width: auto; display: inline-block;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseSelected">
    @foreach (var wh in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleStateChanged;
    }

    private void OnWarehouseSelected(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        if (!string.IsNullOrEmpty(id))
        {
            WarehouseState.SetWarehouse(id);
        }
    }

    private void HandleStateChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleStateChanged;
    }
}

@using sv_76158056ed7642f2afd49f8805c0050a.Services
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

@if (_alertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@_alertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private int _alertCount;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.LastKnownCount;
        AlertService.OnAlertCountUpdated += HandleAlertUpdated;
    }

    private void HandleAlertUpdated(int count)
    {
        _alertCount = count;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountUpdated -= HandleAlertUpdated;
    }
}

