@page "/dashboard"
@using sv_76158056ed7642f2afd49f8805c0050a.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">Current Warehouse</h5>
        <p class="card-text fs-4">
            @WarehouseStateService.AvailableWarehouses
                .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId).Name
        </p>
        <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
    </div>
</div>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Low-Stock Alerts
            @if (_alertCount > 0)
            {
                <span class="badge bg-danger ms-2">@_alertCount items</span>
            }
            else
            {
                <span class="badge bg-success ms-2">All stocked</span>
            }
        </h5>
        <p class="card-text">
            Polling every 10 seconds for items below minimum stock levels.
        </p>
        <p class="text-muted">Last checked: @_lastChecked.ToString("HH:mm:ss")</p>
    </div>
</div>

@code {
    private int _alertCount;
    private DateTime _lastChecked = DateTime.Now;

    protected override void OnInitialized()
    {
        _alertCount = AlertService.LastKnownCount;
        AlertService.OnAlertCountUpdated += HandleAlertUpdated;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;

        // Start polling when this page becomes visible.
        AlertService.Subscribe();
    }

    private void HandleAlertUpdated(int count)
    {
        _alertCount = count;
        _lastChecked = DateTime.Now;
        InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        // Stop polling when user navigates away.
        AlertService.Unsubscribe();
        AlertService.OnAlertCountUpdated -= HandleAlertUpdated;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

